helpers:
let mlxNotifLimit=4,mlxNotifQuery='';
function mlxNoticeTarget(n){
 const words=[n.target||'',n.key||'',n.title||'',n.text||''].join(' ').toLowerCase();
 if(/update|version|release|install|restart/.test(words))return {page:'settings',view:'updates',label:'Software Updates'};
 if(/expense|cash.?flow|cost|spend/.test(words))return {page:'expenses',label:'Expenses'};
 if(/receipt|patient record|patient list|patient history/.test(words))return {page:'patients',label:'Patients & Receipts'};
 if(/patient|registration|new visit/.test(words))return {page:'reception',label:'Reception'};
 if(/radiology|report|x.?ray|ultrasound|ct scan|scan result/.test(words))return {page:'reports',label:'Radiology Reports'};
 if(/rate list|catalogue|test pricing|test rate/.test(words))return {page:'ratelist',label:'Rate List'};
 if(/doctor|staff|user permissions|admin/.test(words))return {page:'admin',label:'Admin & Users'};
 if(/notification|message setting|whatsapp/.test(words))return {page:'settings',view:words.includes('whatsapp')?'whatsapp':'mlxnotifications',label:'Settings'};
 if(/earning|revenue|collection|sale|income|profit|business insight|congratulations/.test(words))return {page:'earnings',label:'Total Earning'};
 return {page:'dashboard',label:'Dashboard'};
}
function mlxNoticeRead(n){if(n.read)return;n.read=true;n.readAt=Date.now();persistNotices(notices);renderNotices()}
function mlxNoticeOpen(n){
 const target=mlxNoticeTarget(n);
 const nav=document.querySelector('#nav button[data-page="'+target.page+'"]');
 if(!nav||nav.disabled||nav.hidden||getComputedStyle(nav).display==='none'){
   // Do not bypass role restrictions; keep the original notice available.
   const box=$('mlx-notif-items');if(box){const msg=document.createElement('p');msg.className='mlx-notif-access';msg.textContent='This section is not available to the current user.';box.prepend(msg)}
   return;
 }
 mlxNoticeRead(n);
 if(notifyPanel)notifyPanel.hidden=true;
 nav.click();
 if(target.view){
   window.setTimeout(()=>{
     const item=document.querySelector('#adcSettingsList [data-open-settings="'+target.view+'"]')||document.querySelector('[data-open-settings="'+target.view+'"]');
     if(item&&!item.disabled)item.click();
   },160);
 }
}
function mlxNotifDay(timestamp){
 const date=new Date(timestamp||Date.now());if(!Number.isFinite(date.getTime()))return 'Earlier';
 const today=new Date(),yesterday=new Date(today);yesterday.setDate(today.getDate()-1);
 const stamp=d=>[d.getFullYear(),d.getMonth(),d.getDate()].join('-');
 if(stamp(date)===stamp(today))return 'Today';
 if(stamp(date)===stamp(yesterday))return 'Yesterday';
 return date.toLocaleDateString('en-PK',{day:'numeric',month:'long',year:'numeric'});
}
function mlxNotifPlace(){
 const top=document.querySelector('#app .top')||$('adc85Titlebar');
 const edge=top?.getBoundingClientRect()?.bottom||64;
 const y=Math.max(64,Math.min(window.innerHeight-110,Math.round(edge+12)));
 if(notifyPanel)notifyPanel.style.setProperty('--mlx-notif-top',y+'px');
 if(toastHost)toastHost.style.setProperty('--mlx-notif-top',y+'px');
}

render:
function renderNotices(){
 const box=$('mlx-notif-items');if(!box)return;
 mlxNotifPlace();
 box.replaceChildren();
 const unread=notices.filter(n=>!n.read).length;
 const dot=document.querySelector('#mlx-notif-btn .mlx-dot');if(dot)dot.hidden=!unread;
 const tab=notifyPanel?.dataset.notifTab==='history'?'history':'inbox';
 $('mlx-notif-inbox')?.setAttribute('aria-pressed',String(tab==='inbox'));
 $('mlx-notif-history')?.setAttribute('aria-pressed',String(tab==='history'));
 const clear=$('mlx-clear-history');if(clear)clear.hidden=tab!=='history';
 const inboxTab=$('mlx-notif-inbox');if(inboxTab)inboxTab.textContent='Inbox ('+unread+')';
 const historyTab=$('mlx-notif-history');if(historyTab)historyTab.textContent='History';
 const panelHeading=notifyPanel?.querySelector('.mlx-panel-head h2');if(panelHeading)panelHeading.textContent='Notifications';
 let search=$('mlx-notif-search');
 if(!search){
   search=document.createElement('input');search.type='search';search.id='mlx-notif-search';
   search.placeholder='Search notifications';search.setAttribute('aria-label','Search notifications');
   const tabs=notifyPanel?.querySelector('.mlx-notif-tabs');if(tabs)tabs.insertAdjacentElement('afterend',search);
   search.addEventListener('input',()=>{mlxNotifQuery=search.value.trim().toLowerCase();mlxNotifLimit=4;renderNotices()});
 }
 if(search&&search.value!==mlxNotifQuery)search.value=mlxNotifQuery;
 const query=mlxNotifQuery;
 const items=notices.filter(n=>(tab==='history'?n.read:!n.read)&&(!query||[n.title,n.text,n.key].join(' ').toLowerCase().includes(query)))
   .sort((a,b)=>(b.time||0)-(a.time||0));
 if(!items.length){
   const empty=document.createElement('div');empty.className='mlx-notif-empty';
   empty.innerHTML='<span aria-hidden="true">✓</span><strong></strong><p></p>';
   empty.querySelector('strong').textContent=tab==='history'?'No history yet':'You are all caught up';
   empty.querySelector('p').textContent=tab==='history'?'Read notifications will appear here grouped by date.':'New alerts will appear in your Inbox.';
   box.append(empty);return;
 }
 let previousDate='';
 items.slice(0,mlxNotifLimit).forEach(n=>{
   if(tab==='history'){
     const group=mlxNotifDay(n.time);
     if(group!==previousDate){
       const day=document.createElement('div');day.className='mlx-notif-date';day.textContent=group;box.append(day);previousDate=group;
     }
   }
   const article=document.createElement('article');article.className='mlx-notif-card';article.dataset.kind=n.kind||'info';article.tabIndex=0;article.setAttribute('role','group');article.title='Open '+mlxNoticeTarget(n).label;article.addEventListener('click',e=>{if(!e.target.closest('button'))mlxNoticeOpen(n)});article.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===article){e.preventDefault();mlxNoticeOpen(n)}});
   const mark=document.createElement('span');mark.className='mlx-nicon';mark.setAttribute('aria-hidden','true');
   mark.textContent=n.kind==='success'?'✓':n.kind==='warning'?'!':'↗';
   const body=document.createElement('div');body.className='mlx-notif-body';
   const title=document.createElement('strong');title.textContent=n.title||'Notification';
   const content=document.createElement('p');content.textContent=n.text||'';
   const meta=document.createElement('small');meta.textContent=new Date(n.time||Date.now()).toLocaleString('en-PK',{dateStyle:'medium',timeStyle:'short'});
   const actions=document.createElement('div');actions.className='mlx-notif-actions';
   const link=document.createElement('button');link.type='button';link.className='mlx-notif-open';
   link.textContent='Open '+mlxNoticeTarget(n).label;link.addEventListener('click',()=>mlxNoticeOpen(n));
   const markRead=document.createElement('button');markRead.type='button';markRead.className='mlx-notif-mark';
   if(!n.read){markRead.textContent='Mark as read';markRead.addEventListener('click',()=>mlxNoticeRead(n));actions.append(link,markRead)}
   else{actions.append(link)}
   body.append(title,content,meta,actions);article.append(mark,body);box.append(article);
 });
 if(items.length>mlxNotifLimit){
   const more=document.createElement('button');more.type='button';more.className='mlx-notif-more';
   more.textContent='Show more ('+(items.length-mlxNotifLimit)+' remaining)';more.addEventListener('click',()=>{mlxNotifLimit+=4;renderNotices()});box.append(more);
 }
}

popup:
function popup(n){
 if(!toastHost)return;
 mlxNotifPlace();
 while(toastHost.querySelectorAll('.mlx-toast').length>=2)toastHost.firstElementChild?.remove();
 const el=document.createElement('div');el.className='mlx-toast mlx-pill-toast';el.dataset.kind=n.kind||'info';
 const open=document.createElement('button');open.type='button';open.className='mlx-pill-open';
 open.title='Open '+mlxNoticeTarget(n).label;
 const icon=document.createElement('span');icon.className='mlx-pill-icon';icon.setAttribute('aria-hidden','true');
 icon.textContent=n.kind==='warning'?'!':n.kind==='success'?'✓':'↗';
 const copy=document.createElement('span');copy.className='mlx-pill-copy';
 const heading=document.createElement('strong');heading.textContent=n.title||'Notification';
 const details=document.createElement('small');details.textContent=n.text||'';
 copy.append(heading,details);open.append(icon,copy);open.onclick=()=>{el.remove();mlxNoticeOpen(n)};
 const close=document.createElement('button');close.type='button';close.className='mlx-pill-close';close.setAttribute('aria-label','Dismiss notification');close.textContent='×';close.onclick=()=>el.remove();
 el.append(open,close);toastHost.append(el);
 let timeout=window.setTimeout(()=>{el.classList.add('mlx-pill-exit');window.setTimeout(()=>el.remove(),240)},n.kind==='warning'?11000:7500);
 el.addEventListener('pointerenter',()=>window.clearTimeout(timeout),{once:true});
}
